// Una sola corrida del Actor ETL con todos los .txt subidos.
if ($input.all().length === 0) throw new Error('No hay .txt en la carpeta 01_crudo de Drive.');
return [{ json: { kvStoreId: $('Abrir KV store crudo').first().json.data.id, noMedidoComoNegativo: true } }];

// El EDA lee el dataset limpio directo del store del run del ETL (sin pasar por Drive).
const p = $('Parametros').first().json;
return [{ json: { kvStoreId: $input.first().json.data.defaultKeyValueStoreId, claveDataset: 'enfr_armonizado.csv',
  anio: Number(p.anio), afBajo: Number(p.af_bajo) } }];

// Filtra el año a predecir y arma lotes con la entrada que espera el Actor de inferencia:
// { registros: [ {id, edad, mujer, ...features} ], incluirEntrada: false }
const p = $('Parametros').first().json;
const anio = Number(p.anio), lote = Number(p.lote_inferencia) || 3000;
const FEATURES = ['provincia', 'region', 'mujer', 'edad', 'nivel_instruccion', 'tiene_cobertura',
  'condicion_actividad', 'quintil_ingreso', 'cant_componentes', 'salud_autopercibida', 'tabaco',
  'actividad_fisica', 'alcohol_regular_riesgo', 'alcohol_episodico', 'fv_promedio_diario', 'cumple_5_fyv',
  'peso_kg', 'talla_cm', 'colesterol_medido', 'colesterol_alto', 'diabetes'];
const META = ['hta', 'grupo_etario', 'mujer', 'provincia', 'peso_rel'];
const texto = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/^\uFEFF/, '');
const lineas = texto.split(/\r?\n/).filter(l => l.length);
const cab = lineas[0].split(',').map(c => c.replace(/"/g, '').trim());
const idx = Object.fromEntries(cab.map((c, i) => [c, i]));
for (const c of ['id_unico', 'anio', ...FEATURES]) if (!(c in idx)) throw new Error(`enfr_armonizado.csv no tiene la columna ${c}`);
const num = v => (v === undefined || v === '' || Number.isNaN(Number(v))) ? null : Number(v);
const personas = [];
for (let k = 1; k < lineas.length; k++) {
  const f = lineas[k].split(',').map(v => v.replace(/"/g, ''));
  if (num(f[idx.anio]) !== anio) continue;
  const reg = { id: f[idx.id_unico] };
  for (const c of FEATURES) reg[c] = num(f[idx[c]]);
  const meta = { id: reg.id };
  for (const c of META) meta[c] = c in idx ? num(f[idx[c]]) : null;
  personas.push({ reg, meta });
}
if (personas.length === 0) throw new Error(`El dataset limpio no tiene personas del año ${anio}.`);
const out = [];
for (let i = 0; i < personas.length; i += lote) {
  const parte = personas.slice(i, i + lote);
  out.push({ json: { registros: parte.map(x => x.reg), incluirEntrada: false, meta: parte.map(x => x.meta) } });
}
console.log(`${personas.length} personas de ${anio} en ${out.length} lotes`);
return out;

// Une las predicciones con los datos de cada persona y arma los dos CSV del dashboard.
const anio = Number($('Parametros').first().json.anio);
const personas = new Map($('Armar lotes para el modelo').all().flatMap(i => i.json.meta).map(m => [String(m.id), m]));
const preds = $input.all().map(i => i.json).filter(p => p.estado === 'ok');
if (preds.length === 0) throw new Error('El Actor de inferencia no devolvió predicciones válidas.');
const errores = $input.all().length - preds.length;
if (errores) console.log(`${errores} registros con error en la inferencia (se excluyen).`);

const GRUPO = { 1: '18-24', 2: '25-34', 3: '35-49', 4: '50-64', 5: '65+' };
const esc = v => (v === null || v === undefined) ? '' : String(v);
const aCsv = (cols, filas) => [cols.join(','), ...filas.map(f => cols.map(c => esc(f[c])).join(','))].join('\n') + '\n';

const filas = preds.map(p => {
  const d = personas.get(String(p.id)) || {};
  return { id: p.id, probabilidad_hta: p.probabilidad_hta, alerta: p.alerta, nivel_riesgo: p.nivel_riesgo,
           hta: d.hta ?? '', grupo_etario: GRUPO[d.grupo_etario] || '', mujer: d.mujer ?? '', provincia: d.provincia ?? '',
           peso_rel: d.peso_rel ?? 1 };
});
const csvPersonas = aCsv(['id', 'probabilidad_hta', 'alerta', 'nivel_riesgo', 'hta', 'grupo_etario', 'mujer', 'provincia', 'peso_rel'], filas);

const r3 = x => Math.round(x * 1000) / 1000;
const kpi = (grupo, fs) => {
  const w = fs.reduce((s, f) => s + Number(f.peso_rel || 1), 0);
  const wAlerta = fs.filter(f => f.alerta === 1).reduce((s, f) => s + Number(f.peso_rel || 1), 0);
  const conocidas = fs.filter(f => f.hta === 0 || f.hta === 1);
  const tp = conocidas.filter(f => f.alerta === 1 && f.hta === 1).length;
  const pos = conocidas.filter(f => f.hta === 1).length;
  const alertas = conocidas.filter(f => f.alerta === 1).length;
  return { anio, grupo, personas: fs.length, pct_poblacion_en_alerta: r3(100 * wAlerta / w),
           prob_media: r3(fs.reduce((s, f) => s + Number(f.probabilidad_hta), 0) / fs.length),
           recall_hta: pos ? r3(tp / pos) : '', precision_hta: alertas ? r3(tp / alertas) : '',
           hipertensos_detectados: tp, hipertensos_declarados: pos };
};
const kpis = [kpi('Total', filas), ...Object.values(GRUPO).map(g => kpi(g, filas.filter(f => f.grupo_etario === g)))];
const csvKpi = aCsv(Object.keys(kpis[0]), kpis);

const bin = (texto, nombre) => this.helpers.prepareBinaryData(Buffer.from(texto, 'utf8'), nombre, 'text/csv');
return [
  { json: { key: `enfr_riesgo_${anio}.csv`, actor: 'Inferencia' }, binary: { data: await bin(csvPersonas, `enfr_riesgo_${anio}.csv`) } },
  { json: { key: 'enfr_kpi_riesgo.csv', actor: 'Inferencia' }, binary: { data: await bin(csvKpi, 'enfr_kpi_riesgo.csv') } }
];

// Un item por cada CSV a recoger, con el store del run que lo generó.
const p = $('Parametros').first().json;
const lista = s => s.split(',').map(x => x.trim()).filter(Boolean);
const store = nodo => { try { return $(nodo).last().json.data.defaultKeyValueStoreId; } catch (e) { return null; } };
const fuentes = [
  ['ETL', store('Estado ETL'), lista(p.salidas_etl)],
  ['EDA', store('Estado EDA'), lista(p.salidas_eda)],
];
const out = [];
for (const [actor, kv, claves] of fuentes) {
  if (!kv) continue;
  for (const key of claves) out.push({ json: { actor, key, kv_store_id: kv } });
}
return out;

// Le devuelve a cada archivo su nombre (la descarga por HTTP lo pierde) y descarta los que no existían.
const out = [];
for (const [i, item] of $input.all().entries()) {
  const origen = $('Archivos a recoger').itemMatching(i).json;
  if (!item.binary || !item.binary.data) { console.log(`No se encontró ${origen.key} en el store del ${origen.actor}`); continue; }
  item.json = { key: origen.key, actor: origen.actor };
  item.binary.data.fileName = origen.key;
  item.binary.data.mimeType = 'text/csv';
  out.push(item);
}
return out;

// Solo los CSV chicos que lee el dashboard (el dataset limpio queda solo en Drive).
const p = $('Parametros').first().json;
const permitidos = new Set(p.archivos_github.split(',').map(s => s.trim()));
const out = [];
for (const [i, item] of $input.all().entries()) {
  if (!permitidos.has(item.json.key)) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({ json: {
    path: `data/${item.json.key}`,
    url: `https://api.github.com/repos/${p.github_repo}/contents/data/${item.json.key}`,
    branch: p.github_branch,
    content: buf.toString('base64')
  } });
}
return out;
